package com.xavier.backend.customers.model;

import com.xavier.backend.customers.model.dto.PhoneView;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.util.Objects;
import java.util.UUID;
import org.hibernate.annotations.UuidGenerator;

/**
 * A phone of a customer, stored as its digits ({@code UNIQUE(customer_id, digits)}). {@code digits_reversed}, which
 * the suffix search scans, is generated by the database and not mapped. At most one phone is primary.
 */
@Entity
@Table(schema = "customers", name = "customer_phone")
public class CustomerPhone {

    @Id
    @UuidGenerator(style = UuidGenerator.Style.VERSION_7)
    private UUID id;

    @Column(nullable = false, updatable = false)
    private UUID customerId;

    @Column(nullable = false, updatable = false, length = 20)
    private String digits;

    @Column(length = 40)
    private String label;

    @Column(name = "is_primary", nullable = false)
    private boolean primary;

    protected CustomerPhone() {
        // JPA
    }

    public static CustomerPhone of(UUID customerId, PhoneNumber number, String label, boolean primary) {
        CustomerPhone phone = new CustomerPhone();
        phone.customerId = Objects.requireNonNull(customerId, "customerId");
        phone.digits = number.digits();
        phone.label = Text.optional(label);
        phone.primary = primary;
        return phone;
    }

    /** Another phone of the customer became the primary one. */
    public void demote() {
        primary = false;
    }

    public PhoneView toView() {
        return new PhoneView(id, digits, label, primary);
    }

    public UUID getId() {
        return id;
    }

    public UUID getCustomerId() {
        return customerId;
    }

    public String getDigits() {
        return digits;
    }

    public boolean isPrimary() {
        return primary;
    }
}
